(()=>{"use strict";let e=window.PluginBaseClass;window.PluginManager.register("UmiPasswordRulePlugin",class extends e{init(){this._registerEvents(),this._validate()}_registerEvents(){this.el.addEventListener("input",()=>{this._validate()}),this.el.addEventListener("blur",()=>{this._validate()})}_validate(){let e=this.el.value||"";e.length>=10&&/[a-z]/.test(e)&&/[A-Z]/.test(e)&&/[0-9]/.test(e)&&/[^A-Za-z0-9]/.test(e)?this.el.setCustomValidity(""):this.el.setCustomValidity("Das Passwort muss mindestens 10 Zeichen sowie Großbuchstaben, Kleinbuchstaben, Zahl und Sonderzeichen enthalten."),this.el.reportValidity()}},'[name="password"]')})();